package floydwarshall.graph;

import java.util.Objects;

/**
 * An immutable directed edge between two vertices, weighted by a value of type
 * {@code W}.
 *
 * <p>Vertices are identified by their zero-based index within a
 * {@link WeightedGraph}. Weights may be negative; Floyd-Warshall supports
 * negative edge weights (and can detect negative cycles).
 *
 * @param <W>    the weight type
 * @param from   the source vertex index
 * @param to     the destination vertex index
 * @param weight the cost of traversing the edge (non-null)
 */
public record Edge<W>(int from, int to, W weight) {

    public Edge {
        if (from < 0) {
            throw new IllegalArgumentException("from must be non-negative, got " + from);
        }
        if (to < 0) {
            throw new IllegalArgumentException("to must be non-negative, got " + to);
        }
        Objects.requireNonNull(weight, "weight");
    }
}

