package floydwarshall.algorithm;

import floydwarshall.graph.Edge;
import floydwarshall.graph.WeightedGraph;
import floydwarshall.matrix.SquareMatrix;
import floydwarshall.weight.WeightSystem;

import java.util.Objects;

/**
 * Computes all-pairs shortest paths using the Floyd-Warshall algorithm over an
 * arbitrary weight type {@code W}, as defined by a {@link WeightSystem}.
 *
 * <p>The algorithm runs in {@code O(V^3)} time and {@code O(V^2)} space and
 * supports negative weights. Negative-weight cycles are detected rather than
 * silently producing meaningless distances. The input {@link WeightedGraph} is
 * never mutated; results are returned in a fresh {@link AllPairsShortestPaths}.
 *
 * @param <W> the weight type
 */
public final class FloydWarshallSolver<W> {

    private final WeightSystem<W> weights;

    public FloydWarshallSolver(WeightSystem<W> weights) {
        this.weights = Objects.requireNonNull(weights, "weights");
    }

    /** Solves all-pairs shortest paths for the given graph. */
    public AllPairsShortestPaths<W> solve(WeightedGraph<W> graph) {
        int n = graph.vertexCount();
        SquareMatrix<W> dist = SquareMatrix.empty(n);
        NextHopTable next = new NextHopTable(n);

        for (int v = 0; v < n; v++) {
            dist.set(v, v, weights.zero());
            next.set(v, v, v);
        }
        // Keep the cheapest weight when parallel edges share an ordered pair.
        for (Edge<W> e : graph.edges()) {
            W current = dist.getOrNull(e.from(), e.to());
            if (current == null || weights.compare(e.weight(), current) < 0) {
                dist.set(e.from(), e.to(), e.weight());
                next.set(e.from(), e.to(), e.to());
            }
        }
        return run(dist, next);
    }

    private AllPairsShortestPaths<W> run(SquareMatrix<W> dist, NextHopTable next) {
        int n = dist.size();
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                W distIK = dist.getOrNull(i, k);
                if (distIK == null) {
                    continue; // i cannot reach k, so k relays nothing for row i
                }
                for (int j = 0; j < n; j++) {
                    W distKJ = dist.getOrNull(k, j);
                    if (distKJ == null) {
                        continue;
                    }
                    W candidate = weights.sum(distIK, distKJ);
                    W existing = dist.getOrNull(i, j);
                    if (existing == null || weights.compare(candidate, existing) < 0) {
                        dist.set(i, j, candidate);
                        next.set(i, j, next.get(i, k));
                    }
                }
            }
        }
        return new AllPairsShortestPaths<>(dist, next, hasNegativeCycle(dist));
    }

    private boolean hasNegativeCycle(SquareMatrix<W> dist) {
        for (int i = 0; i < dist.size(); i++) {
            W self = dist.getOrNull(i, i);
            if (self != null && weights.compare(self, weights.zero()) < 0) {
                return true;
            }
        }
        return false;
    }
}

